import React, { useEffect, useMemo, useState } from "react";
import "./ExperienceSelector.css";
import "../projects/ProjectManager.css";
import cotecmarLogo from "../../../assets/images/logo.png";
import { FaMapMarkerAlt, FaInfoCircle, FaImage, FaList, FaThLarge, FaSearch, FaFilter, FaArrowRight, FaShip, FaSignOutAlt, FaUserShield, FaChevronRight, FaPlay, FaBars, FaTimes, FaCog, FaLock, FaUsers, FaShieldAlt, FaKey, FaChevronDown, FaUserCircle, FaMoon, FaSun, FaImages, FaArrowLeft, FaAnchor, FaWater } from "react-icons/fa";
import DynamicNavbar from "../../layout/Navbar/DynamicNavbar";
import projectService from "../../../api/services/projectService";
import authService from "../../../api/services/authService";
import { useNavigate } from "react-router-dom";
import PasswordSettings from "../auth/PasswordSettings";
import SceneCalibrationTool from "../experiences/SceneCalibrationTool";

const ICONS = { FaShip, FaCog, FaAnchor, FaWater, FaImage, FaMapMarkerAlt };

const ExperienceSelector = ({ onExperienceSelect, onViewDetails, onBackToManager, onAccessAdmin, onLogout, darkMode, onToggleDarkMode }) => {
  const navigate = useNavigate();
  const currentUser = authService.getCurrentUser();
  const [menuOpen, setMenuOpen] = useState(false);
  const [showPasswordSettings, setShowPasswordSettings] = useState(false);
  const [showSceneCalibration, setShowSceneCalibration] = useState(false);
  const [showSidebar, setShowSidebar] = useState(false);

  const [project, setProject] = useState(null);

  useEffect(() => {
    (async () => {
      const active = await projectService.getActiveProject();
      console.log("INFO DE ESCENAS EN EL PROYECTO...", active);
      setProject(active);
    })();
  }, []);

  const experiences = useMemo(() => {
    if (!project) return [];

    if (Array.isArray(project.experiences) && project.experiences.length > 0) {
      return project.experiences.map((exp) => ({
        id: exp.id,
        title: exp.name,
        description: exp.description || "",
        iconName: exp.icon || "FaMapMarkerAlt",
        startScene: exp.startScene || "",
        image: exp.image || "",
      }));
    }

    const sceneEntries = Object.entries(project.scenes || {});
    return sceneEntries.map(([sceneKey, scene]) => ({
      id: sceneKey,
      title: scene.title || sceneKey,
      description: "Escena 360°",
      iconName: "FaMapMarkerAlt",
      startScene: sceneKey,
      image: scene.image || "",
    }));
  }, [project]);

  const handleClick = (exp) => {
    const target = exp.startScene || exp.id;

    localStorage.setItem("lastSceneKey", target);

    onExperienceSelect(target);
  };

  if (showPasswordSettings) {
    return <PasswordSettings onClose={() => setShowPasswordSettings(false)} />;
  }

  if (showSceneCalibration) {
    return <SceneCalibrationTool onClose={() => setShowSceneCalibration(false)} />;
  }

  return (
    <>      <DynamicNavbar
        showBackButton={true}
        title={project?.name || "Project Management"}
        subtitle="Zonas disponibles"
      >
        <div className="profile-container" style={{ position: 'relative', marginLeft: '8px' }}>
          <button className="profile-btn" onClick={() => setMenuOpen((v) => !v)}>
            <div className="avatar-wrapper">
              <FaUserCircle className="user-avatar-icon" />
            </div>
            <span className="avatar-username">{currentUser?.name || 'Perfil'}</span>
            <FaChevronDown style={{ fontSize: '12px', color: 'inherit' }} />
          </button>
          {menuOpen && (
            <div className="profile-dropdown-menu" onMouseLeave={() => setMenuOpen(false)}>
              <div className="dropdown-user-info">
                <p className="user-name">{currentUser?.name || 'Usuario'}</p>
                <p className="user-role">{currentUser?.email || ''}</p>
              </div>
              <hr className="dropdown-divider" />
              <button className="dropdown-item" onClick={() => { setMenuOpen(false); navigate('/gallery'); }}>
                <FaImages className="dropdown-icon" /> Galería de proyectos
              </button>
              <button className="dropdown-item" onClick={() => { setMenuOpen(false); setShowPasswordSettings(true); }}>
                <FaKey className="dropdown-icon" /> Cambiar contraseña
              </button>
              <button className="dropdown-item" onClick={() => { setMenuOpen(false); setShowSceneCalibration(true); }}>
                <FaMapMarkerAlt className="dropdown-icon" /> Calibrar orientación
              </button>
              <hr className="dropdown-divider" />
              <button className="dropdown-item logout" onClick={() => {
                setMenuOpen(false);
                authService.logout();
                navigate("/login");
              }}>
                <FaSignOutAlt className="dropdown-icon" /> Cerrar sesión
              </button>
            </div>
          )}
        </div>
      </DynamicNavbar>

      <div className="experience-selector-container">


      {onBackToManager && (
        <button className="back-to-manager-btn" onClick={onBackToManager} title="Volver">
          <FaArrowLeft /> Volver
        </button>
      )}

      {/* Hero Card Container */}
      <div className="experience-hero-card">
        <div className="hero-image-container">
          {project?.thumbnail || project?.image ? (
            <img 
              src={project.thumbnail || project.image} 
              alt={project.name} 
              className="hero-project-image"
              onError={(e) => { e.currentTarget.onerror = null; e.currentTarget.src = "/images/default_image.png"; }} 
            />
          ) : (
            <div className="hero-logo-fallback">
              <FaImage size={64} color="#cbd5e1" />
            </div>
          )}
        </div>
        <div className="hero-title-container">
          <h1>{project?.name || "PROYECTO"}</h1>
        </div>
      </div>

      {/* Main Content Section */}
      <div className="experience-content-section">
        
        {/* Toolbar */}
        <div className="experience-toolbar">
          <h2 className="section-title">Zonas disponibles</h2>
          
          <div className="search-container">
            <FaSearch className="search-icon" />
            <input type="text" placeholder="Buscar zonas..." className="search-input" />
          </div>

          <div className="view-toggle-container">
            <div className="toggle-wrapper">
              <button className="view-toggle-btn active" title="Vista cuadrícula">
                <FaThLarge />
              </button>
              <button className="view-toggle-btn" title="Vista lista">
                <FaList />
              </button>
            </div>
          </div>
        </div>

        {/* Zones Grid */}
        <div className="experience-grid">
          {experiences.map((exp) => {
            const IconComponent = ICONS[exp.iconName] || FaMapMarkerAlt;

            return (
              <div key={exp.id} className="experience-card" onClick={() => handleClick(exp)}>
                <div className="experience-content">
                  <div className="experience-icon">
                    <IconComponent />
                  </div>
                  <h3>{exp.title}</h3>
                </div>
              </div>
            );
          })}

          {project && experiences.length === 0 && (
            <div className="empty-state">
              <p>Este proyecto no tiene zonas ni escenas configuradas.</p>
            </div>
          )}
        </div>

      </div>
      </div>
    </>
  );
};

export default ExperienceSelector;
