import React, { useMemo, useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaSearch, FaFilter, FaThLarge, FaList, FaSignOutAlt, FaEye, FaLock, FaLayerGroup, FaBars, FaTimes, FaCog, FaUsers, FaShieldAlt, FaUserCircle, FaChevronDown, FaImages, FaTrash, FaCogs, FaArrowRight, FaEnvelope, FaPhone, FaUserEdit, FaKey, FaFolderOpen } from 'react-icons/fa';
import projectService from '../../../api/services/projectService';
import authService from '../../../api/services/authService';
import DynamicNavbar from '../../layout/Navbar/DynamicNavbar';
import cotecmarLogo from '../../../assets/images/logo.png';
import fallbackProjectImage from '../../../assets/images/360.png';
import './ProjectGallery.css';

const ProjectGallery = () => {
  const navigate = useNavigate();
  const [projects, setProjects] = useState([]);
  const [filteredProjects, setFilteredProjects] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const filterStatus = 'all';
  const [menuOpen, setMenuOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [passwordOpen, setPasswordOpen] = useState(false);
  const [profileForm, setProfileForm] = useState({ name: '', email: '', phone: '' });
  const [profileSaving, setProfileSaving] = useState(false);
  const [profileError, setProfileError] = useState('');
  const [profileSuccess, setProfileSuccess] = useState('');
  const [pwdForm, setPwdForm] = useState({ currentPassword: '', newPassword: '', confirmPassword: '' });
  const [pwdSaving, setPwdSaving] = useState(false);
  const [pwdError, setPwdError] = useState('');
  const [pwdSuccess, setPwdSuccess] = useState('');
  const [currentUserState, setCurrentUserState] = useState(() => authService.getCurrentUser());

  const [showSidebar, setShowSidebar] = useState(false);
  const sidebarRef = useRef(null);

  const currentUser = useMemo(() => currentUserState || authService.getCurrentUser(), [currentUserState]);

  useEffect(() => {
    const handleSidebarClickOutside = (event) => {
      if (sidebarRef.current && !sidebarRef.current.contains(event.target)) {
        const hamburgerBtn = document.querySelector(".hamburger-btn");
        if (!hamburgerBtn || !hamburgerBtn.contains(event.target)) {
          setShowSidebar(false);
        }
      }
    };
    if (showSidebar) {
      document.addEventListener("mousedown", handleSidebarClickOutside);
    }
    return () => document.removeEventListener("mousedown", handleSidebarClickOutside);
  }, [showSidebar]);

  useEffect(() => {
    const loadProjects = async () => {
      const allProjects = await projectService.getAllProjects();
      setProjects(allProjects);
      setFilteredProjects(allProjects);
    };
    loadProjects();
  }, []);

  useEffect(() => {
    const user = authService.getCurrentUser();
    if (!user) return;
    setCurrentUserState(user);
    setProfileForm({
      name: user.name || '',
      email: user.email || '',
      phone: user.phone || '',
    });
  }, []);

  useEffect(() => {
    let filtered = projects;

    if (searchTerm) {
      filtered = filtered.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.vesselType?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.description?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    if (filterStatus !== 'all') {
      filtered = filtered.filter(p => p.status === filterStatus);
    }

    setFilteredProjects(filtered);
  }, [searchTerm, filterStatus, projects]);

  const handleProjectClick = (projectId) => {
    navigate(`/project/${projectId}`);
  };

  const handleLogout = () => {
    authService.logout();
    navigate('/login');
  };

  const handlePagesInformationClick = (projectId) => {
    navigate(`/project/${projectId}/details`);
  };

  const openProfile = () => {
    setMenuOpen(false);
    setProfileError('');
    setProfileSuccess('');
    const user = authService.getCurrentUser();
    setProfileForm({
      name: user?.name || '',
      email: user?.email || '',
      phone: user?.phone || '',
    });
    setProfileOpen(true);
  };

  const openPassword = () => {
    setMenuOpen(false);
    setPwdError('');
    setPwdSuccess('');
    setPwdForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
    setPasswordOpen(true);
  };

  const handleSaveProfile = async (e) => {
    e.preventDefault();
    setProfileSaving(true);
    setProfileError('');
    setProfileSuccess('');

    const result = await authService.updateMyProfile({
      name: profileForm.name,
      email: profileForm.email,
      phone: profileForm.phone,
    });

    if (result.success) {
      setCurrentUserState(result.user);
      setProfileSuccess('Información actualizada.');
      setTimeout(() => setProfileOpen(false), 700);
    } else {
      setProfileError(result.error || 'No se pudo actualizar');
    }

    setProfileSaving(false);
  };

  const handleChangePassword = async (e) => {
    e.preventDefault();
    setPwdSaving(true);
    setPwdError('');
    setPwdSuccess('');

    if (pwdForm.newPassword !== pwdForm.confirmPassword) {
      setPwdError('La confirmación no coincide.');
      setPwdSaving(false);
      return;
    }

    const result = await authService.changeMyPassword(pwdForm.currentPassword, pwdForm.newPassword);
    if (result.success) {
      setPwdSuccess('Contraseña actualizada.');
      setTimeout(() => setPasswordOpen(false), 700);
    } else {
      setPwdError(result.error || 'No se pudo cambiar la contraseña');
    }

    setPwdSaving(false);
  };

  const headerTitle = currentUser?.role === 'user' ? 'Galería de Proyectos' : 'Galería de Proyectos';

  return (
    <div className="project-gallery">
     
      <div 
        className={`sidebar-overlay ${showSidebar ? "active" : ""}`} 
        onClick={() => setShowSidebar(false)}
      ></div>
      <div className={`sidebar-menu ${showSidebar ? "open" : ""}`} ref={sidebarRef}>
        <div className="sidebar-header">
          <div className="sidebar-brand-title">
            <img src={cotecmarLogo} alt="COTECMAR" className="sidebar-logo" />
            <span>Navegación</span>
          </div>
          <button 
            className="sidebar-close-btn" 
            onClick={() => setShowSidebar(false)} 
            title="Cerrar Menú"
          >
            <FaTimes />
          </button>
        </div>
        <nav className="sidebar-nav">
          <button 
            className={`sidebar-item ${(currentUser?.role === 'admin' || currentUser?.role === 'project_admin') ? '' : 'active'}`}
            onClick={() => {
              if (currentUser?.role === 'admin' || currentUser?.role === 'project_admin') {
                navigate("/admin");
              }
              setShowSidebar(false);
            }}
          >
            <FaFolderOpen className="sidebar-icon" />
            <span>Mis Proyectos</span>
          </button>
          
          <button 
            className="sidebar-item" 
            style={{ display: currentUser?.role === 'admin' ? 'flex' : 'none' }}
            onClick={() => {
              navigate("/admin/users");
              setShowSidebar(false);
            }}
          >
            <FaUsers className="sidebar-icon" />
            <span>Gestión de Usuarios</span>
          </button>
          
          <button 
            className="sidebar-item" 
            style={{ display: currentUser?.role === 'admin' ? 'flex' : 'none' }}
            onClick={() => {
              navigate("/admin/permissions");
              setShowSidebar(false);
            }}
          >
            <FaShieldAlt className="sidebar-icon" />
            <span>Gestión de Permisos</span>
          </button>
          
          <button 
            className={`sidebar-item ${(currentUser?.role === 'admin' || currentUser?.role === 'project_admin') ? 'active' : ''}`}
            onClick={() => setShowSidebar(false)}
          >
            <FaImages className="sidebar-icon" />
            <span>Galería de Proyecto</span>
          </button>
        </nav>
      </div>

      <DynamicNavbar
        showBackButton={false}
        title="Galería de Proyectos"
        subtitle="Explora y administra los barcos disponibles en la plataforma."
        leftActions={
          <button 
            className="hamburger-btn" 
            onClick={() => setShowSidebar(!showSidebar)}
            title="Abrir Menú"
            style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'transparent', border: 'none', color: 'inherit', fontSize: '20px', cursor: 'pointer', padding: '8px', marginRight: '8px' }}
          >
            <FaBars />
          </button>
        }
      >
        <div className="profile-area" style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
          <button className="profile-button" onClick={() => setMenuOpen((v) => !v)} style={{ display: 'flex', alignItems: 'center', gap: '8px', background: 'transparent', border: 'none', color: 'inherit', cursor: 'pointer', fontSize: '14px', fontWeight: '500' }}>
            <FaUserCircle style={{ fontSize: '20px' }} />
            <span className="profile-name">{currentUser?.name || 'Perfil'}</span>
            <FaChevronDown style={{ fontSize: '12px' }} />
          </button>
            {menuOpen && (
              <div className="profile-menu" onMouseLeave={() => setMenuOpen(false)}>
                <div className="profile-menu-head">
                  <strong>{currentUser?.name || 'Usuario'}</strong>
                  <span>{currentUser?.email || ''}</span>
                </div>
                {(currentUser?.role === 'admin' || currentUser?.role === 'project_admin') && (
                  <button className="profile-menu-item" onClick={() => navigate('/admin')}>
                    <FaCogs /> Panel administrador
                  </button>
                )}
                <button className="profile-menu-item" onClick={openProfile}>
                  <FaUserEdit /> Editar información
                </button>
                <button className="profile-menu-item" onClick={openPassword}>
                  <FaKey /> Cambiar contraseña
                </button>
                <button className="profile-menu-item danger" onClick={handleLogout}>
                  <FaSignOutAlt /> Cerrar sesión
                </button>
              </div>
            )}
          </div>
      </DynamicNavbar>

      <div className="gallery-header-bottom" style={{ 
        maxWidth: '1400px', 
        margin: '32px auto 48px auto', 
        padding: '0 40px', 
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'space-between' 
      }}>
        <div className="gallery-controls-copy" style={{ flex: 1, textAlign: 'left' }}>
          <h2 style={{ fontSize: '28px', fontWeight: 'bold', margin: 0 }}>{headerTitle}</h2>
          <p style={{ marginTop: '8px', opacity: 0.8 }}>
            {currentUser?.role === 'user'
              ? ''
              : 'Explora y administra los barcos disponibles en la plataforma.'}
          </p>
        </div>
        
        <div className="search-container" style={{ flex: 1, display: 'flex', justifyContent: 'center' }}>
          <div className="search-box" style={{ width: '100%', maxWidth: '500px' }}>
            <FaSearch className="search-icon" />
            <input
              type="text"
              placeholder="Buscar proyectos..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{ width: '100%' }}
            />
          </div>
        </div>

        <div style={{ flex: 1 }}></div>
      </div>

      <div className="projects-grid">
        {filteredProjects.length > 0 ? (
          filteredProjects.map(project => (
            <div 
              key={project.id} 
              className="project-card"
            >
              <div className="card-image">
                <img 
                  src={project.thumbnail || fallbackProjectImage} 
                  alt={project.name}
                  onError={(e) => {
                    e.currentTarget.onerror = null;
                    e.currentTarget.src = fallbackProjectImage;
                  }}
                />
                <div className="card-overlay"
                  onClick={() => handleProjectClick(project.id)}
                
                >
                 {/* <FaSyncAlt className='view-icon'/>  */}
                 
                
                  <span>Recorrido 360°</span>
                </div>
              </div>
              
              <div className="card-content">
                <h3>{project.name}</h3>
                <p className="vessel-type">{project.vesselType}</p>
                <p className="description">
                  {project.description?.substring(0, 100)}
                  {project.description?.length > 100 ? '...' : ''}
                </p>
                
                <div className="card-footer">
                  {/* <div className="card-stats">
                    <span className="stat">
                      <FaEye /> {project.experiences?.length || 0} zonas
                    </span>
                    <span className="stat">
                      {Object.keys(project.scenes || {}).length} escenas
                    </span>
                  </div> */}
                  <button
                  className="btn-view"
                  onClick={() => handlePagesInformationClick(project.id)}
                   >
                    Mas Información <FaArrowRight />
                  </button>
                </div>
              </div>
            </div>
          ))
        ) : (
          <div className="no-results">
            <FaSearch className="no-results-icon" />
            <h3>No se encontraron proyectos</h3>
            <p>Intenta con otros términos de búsqueda</p>
          </div>
        )}
      </div>

      <footer className="gallery-footer">
        <p>&copy; 2024 Sistema de Visualización 360°. Todos los derechos reservados.</p>
      </footer>

      {profileOpen && (
        <div className="profile-modal-overlay" onClick={() => setProfileOpen(false)}>
          <div className="profile-modal" onClick={(e) => e.stopPropagation()}>
            <div className="profile-modal-header">
              <div className="profile-modal-title">
                <span className="profile-chip active">Información</span>
              </div>
              <h2>Información Personal</h2>
              <p>Actualiza los datos asociados a tu cuenta.</p>
            </div>
            <form onSubmit={handleSaveProfile} className="profile-form">
              <div className="profile-section">
                <h3>Información básica</h3>
                <div className="profile-grid">
                  <label className="profile-field profile-field--full">
                    <span>Nombre</span>
                    <input
                      value={profileForm.name}
                      onChange={(e) => setProfileForm((p) => ({ ...p, name: e.target.value }))}
                      required
                    />
                  </label>
                  <label className="profile-field profile-field--wide">
                    <span>Correo</span>
                    <div className="profile-input-wrap">
                      <FaEnvelope />
                      <input
                        type="email"
                        value={profileForm.email}
                        onChange={(e) => setProfileForm((p) => ({ ...p, email: e.target.value }))}
                        required
                      />
                    </div>
                  </label>
                  <label className="profile-field">
                    <span>Teléfono</span>
                    <div className="profile-input-wrap">
                      <FaPhone />
                      <input
                        value={profileForm.phone}
                        onChange={(e) => setProfileForm((p) => ({ ...p, phone: e.target.value }))}
                      />
                    </div>
                  </label>
                </div>
              </div>
              {profileError && <div className="profile-error">{profileError}</div>}
              {profileSuccess && <div className="profile-success">{profileSuccess}</div>}
              <div className="profile-actions">
                <button type="button" className="profile-btn secondary" onClick={() => setProfileOpen(false)}>
                  Cancelar
                </button>
                <button type="submit" className="profile-btn primary" disabled={profileSaving}>
                  {profileSaving ? 'Guardando...' : 'Guardar'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {passwordOpen && (
        <div className="profile-modal-overlay" onClick={() => setPasswordOpen(false)}>
          <div className="profile-modal" onClick={(e) => e.stopPropagation()}>
            <div className="profile-modal-header">
              <div className="profile-modal-title">
                <span className="profile-chip active">Seguridad</span>
              </div>
              <h2>Cambiar contraseña</h2>
              <p>Actualiza tu clave de acceso manteniendo protegida tu cuenta.</p>
            </div>
            <form onSubmit={handleChangePassword} className="profile-form">
              <div className="profile-section">
                <h3>Datos de seguridad</h3>
                <div className="profile-grid">
                  <label className="profile-field profile-field--full">
                    <span>Contraseña actual</span>
                    <input
                      type="password"
                      value={pwdForm.currentPassword}
                      onChange={(e) => setPwdForm((p) => ({ ...p, currentPassword: e.target.value }))}
                      required
                    />
                  </label>
                  <label className="profile-field">
                    <span>Nueva contraseña</span>
                    <input
                      type="password"
                      value={pwdForm.newPassword}
                      onChange={(e) => setPwdForm((p) => ({ ...p, newPassword: e.target.value }))}
                      required
                    />
                  </label>
                  <label className="profile-field">
                    <span>Confirmar contraseña</span>
                    <input
                      type="password"
                      value={pwdForm.confirmPassword}
                      onChange={(e) => setPwdForm((p) => ({ ...p, confirmPassword: e.target.value }))}
                      required
                    />
                  </label>
                </div>
              </div>
              {pwdError && <div className="profile-error">{pwdError}</div>}
              {pwdSuccess && <div className="profile-success">{pwdSuccess}</div>}
              <div className="profile-actions">
                <button type="button" className="profile-btn secondary" onClick={() => setPasswordOpen(false)}>
                  Cancelar
                </button>
                <button type="submit" className="profile-btn primary" disabled={pwdSaving}>
                  {pwdSaving ? 'Guardando...' : 'Cambiar'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProjectGallery;

