import React, { useState } from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import { FaArrowLeft, FaMoon, FaSun, FaUserShield, FaSignOutAlt } from "react-icons/fa";
import MapModal from "../../features/maps/MapModal";
import "./DynamicNavbar.css";
import cotecmarLogo from "../../../assets/images/logo.png";
import cotecmarLogoColored from "../../../assets/images/cotecmar-logo.png";
import "../../features/projects/ProjectManager.css";
import { useTheme } from "../../../context/ThemeContext";

const DynamicNavbar = ({
  children,
  leftActions,
  showBackButton = true,
  onBack,
  title = "Portal RV360",
  subtitle = "Sistema de Visualización 360°",
  scenes,
  currentScene,
  onSceneSelect,
}) => {
  const { isLightMode, toggleLightMode } = useTheme();
  const location = useLocation();
  const navigate = useNavigate();
  const { projectId } = useParams();
  const [showMapModal, setShowMapModal] = useState(false);

  const isExperienceView = location.pathname.includes("/experience/");
  const isProjectView = location.pathname.startsWith("/project/") && !isExperienceView;
  const isAdminView = location.pathname.startsWith("/admin");
  const isGalleryView = location.pathname.startsWith("/gallery");
  const isLandingPage = location.pathname === "/";
  const activeStep = isExperienceView ? "viewer" : isProjectView ? "project" : "home";
  
  const isDarkStyle = isAdminView || isGalleryView || !isLightMode;

  const handleBack = () => {
    if (onBack) {
      onBack();
      return;
    }
    if (window.history.length > 1) {
      navigate(-1);
    } else if (projectId) {
      navigate(`/project/${projectId}`);
    } else {
      navigate("/gallery");
    }
  };

  if (isLandingPage) {
    return null;
  }

  return (
    <>
      <header className={`manager-header ${!isDarkStyle ? 'light-navbar' : ''}`} role="banner" style={{position: 'fixed', top: 0, left: 0, right: 0, zIndex: 1000, margin: 0, height: '80px', display: 'flex', alignItems: 'center', backgroundColor: isDarkStyle ? 'rgba(15, 23, 42, 0.95)' : '#ffffff', borderBottom: isDarkStyle ? '1px solid rgba(255,255,255,0.1)' : '1px solid #e2e8f0'}}>
        <div className="manager-header-inner" style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%', padding: '0 24px'}}>
          <div className="manager-brand" style={{display: 'flex', alignItems: 'center', gap: '16px'}}>
            {leftActions}
            {showBackButton && (
              <button className="back-btn" onClick={handleBack} title="Volver" style={{ margin: 0, border: isDarkStyle ? '1px solid rgba(255,255,255,0.2)' : '1px solid #e2e8f0', background: 'transparent', color: isDarkStyle ? 'white' : '#1e3a8a', padding: '8px 16px', borderRadius: '8px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '600', fontSize: '14px' }}>
                <FaArrowLeft /> Atrás
              </button>
            )}
            
            <img src={isDarkStyle ? cotecmarLogo : cotecmarLogoColored} alt="COTECMAR" className="manager-logo" style={{width: '135px', height: 'auto', flexShrink: 0, marginLeft: '8px', transition: 'all 0.5s'}} />
            <div className="manager-brand-text">
              <h1 style={{margin: 0, fontSize: '20px', fontWeight: 'bold', color: isDarkStyle ? '#fff' : '#1e3a8a'}}>{title}</h1>
              <p style={{margin: 0, fontSize: '13px', color: isDarkStyle ? '#cbd5e1' : '#2B5398'}}>{subtitle}</p>
            </div>
          </div>

          <div className="manager-header-actions" style={{display: 'flex', gap: '12px', alignItems: 'center'}}>
            {children}
            <button
              className="navbar-dark-mode-btn"
              onClick={toggleLightMode}
              title={isLightMode ? "Modo Oscuro" : "Modo Claro"}
              style={{display: 'flex', alignItems: 'center', justifyContent: 'center', width: '40px', height: '40px', background: isDarkStyle ? 'rgba(255,255,255,0.1)' : '#f1f5f9', color: isDarkStyle ? 'white' : '#1e3a8a', border: isDarkStyle ? '1px solid rgba(255,255,255,0.2)' : '1px solid #e2e8f0', borderRadius: '8px', cursor: 'pointer'}}
            >
              {isLightMode ? <FaMoon /> : <FaSun />}
            </button>
          </div>
        </div>
      </header>
      <div style={{ height: '56px', width: '100%', display: 'flow-root' }} aria-hidden="true" />

      <MapModal
        isOpen={showMapModal}
        onClose={() => setShowMapModal(false)}
        scenes={scenes}
        currentScene={currentScene}
        onSceneSelect={(sceneKey) => {
          if (onSceneSelect) onSceneSelect(sceneKey);
          setShowMapModal(false);
        }}
      />
    </>
  );
};

export default DynamicNavbar;
