import React, { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { FaUserPlus, FaUserEdit, FaTrash, FaKey, FaShieldAlt, FaEnvelope, FaSearch, FaUserCircle, FaChevronDown, FaBars, FaTimes, FaLayerGroup, FaImages, FaSignOutAlt, FaFolderOpen, FaArrowRight, FaLock, FaCog, FaPhone, FaPlus, FaSave, FaUserCog, FaUsers, FaMapMarkerAlt, FaSun, FaMoon, FaUserShield } from 'react-icons/fa';
import "./UserManagement.css";
import "../projects/ProjectManager.css";
import userService from "../../../api/services/userService";
import ConfirmModal from "../../common/Modal/ConfirmModal";
import ProgressBreadcrumb from "../../ui/ProgressBreadcrumb/ProgressBreadcrumb";
import DynamicNavbar from '../../layout/Navbar/DynamicNavbar';
import cotecmarLogo from "../../../assets/images/logo.png";
import authService from "../../../api/services/authService";
import PasswordSettings from "../auth/PasswordSettings";
import SceneCalibrationTool from "../experiences/SceneCalibrationTool";


const emptyForm = {
  id: null,
  name: "",
  email: "",
  phone: "",
  password: "",
  role: "user",
  isActive: true,
  projectIds: [],
};

const UserManagement = ({ onBack, onLogout, darkMode, onToggleDarkMode }) => {
  const navigate = useNavigate();
  const currentUser = authService.getCurrentUser();
  const sidebarRef = React.useRef(null);

  const [showSidebar, setShowSidebar] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [showPasswordSettings, setShowPasswordSettings] = useState(false);
  const [showSceneCalibration, setShowSceneCalibration] = useState(false);

  const [users, setUsers] = useState([]);
  const [form, setForm] = useState(emptyForm);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [modal, setModal] = useState({
    isOpen: false,
    title: "",
    message: "",
    onConfirm: null,
  });

  useEffect(() => {
    const handleSidebarClickOutside = (event) => {
      if (sidebarRef.current && !sidebarRef.current.contains(event.target)) {
        const hamburgerBtn = document.querySelector(".hamburger-btn");
        if (!hamburgerBtn || !hamburgerBtn.contains(event.target)) {
          setShowSidebar(false);
        }
      }
    };
    if (showSidebar) {
      document.addEventListener("mousedown", handleSidebarClickOutside);
    }
    return () => document.removeEventListener("mousedown", handleSidebarClickOutside);
  }, [showSidebar]);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    setError("");

    try {
      const usersData = await userService.getAllUsers();
      setUsers(usersData);
    } catch (err) {
      setError(err.message || "No se pudo cargar la gestión de usuarios");
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setForm(emptyForm);
    setError("");
    setMessage("");
  };

  const startEdit = (user) => {
    setForm({
      id: user.id,
      name: user.name || "",
      email: user.email || "",
      phone: user.phone || "",
      password: "",
      role: user.role || "user",
      isActive: Boolean(user.isActive),
      projectIds: user.projectIds || [],
    });
    setMessage("");
    setError("");
  };

  const handleChange = (field, value) => {
    setForm((prev) => ({
      ...prev,
      [field]: value,
      ...(field === "role" && value === "admin" ? { projectIds: [] } : {}),
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    setError("");
    setMessage("");

    try {
      const payload = {
        name: form.name,
        email: form.email,
        phone: form.phone,
        password: form.password,
        role: form.role,
        isActive: form.isActive,
        projectIds: form.role === "user" ? form.projectIds : [],
      };

      if (form.id) {
        await userService.updateUser(form.id, payload);
        setMessage("Usuario actualizado correctamente.");
      } else {
        await userService.createUser(payload);
        setMessage("Usuario creado correctamente.");
      }

      await loadData();
      resetForm();
    } catch (err) {
      setError(err.message || "No se pudo guardar el usuario");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = (user) => {
    setModal({
      isOpen: true,
      title: "Eliminar usuario",
      message: `Se eliminará la cuenta de ${user.name}. Esta acción no se puede deshacer.`,
      onConfirm: async () => {
        try {
          await userService.deleteUser(user.id);
          setMessage("Usuario eliminado correctamente.");
          if (form.id === user.id) {
            resetForm();
          }
          await loadData();
        } catch (err) {
          setError(err.message || "No se pudo eliminar el usuario");
        } finally {
          setModal((prev) => ({ ...prev, isOpen: false }));
        }
      },
    });
  };

  if (showPasswordSettings) {
    return <PasswordSettings onClose={() => setShowPasswordSettings(false)} />;
  }
  if (showSceneCalibration) {
    return <SceneCalibrationTool onClose={() => setShowSceneCalibration(false)} />;
  }

  return (

    
    <div className="user-management project-manager">
      <div 
        className={`sidebar-overlay ${showSidebar ? "active" : ""}`} 
        onClick={() => setShowSidebar(false)}
      ></div>
      <div className={`sidebar-menu ${showSidebar ? "open" : ""}`} ref={sidebarRef}>
        <div className="sidebar-header">
          <div className="sidebar-brand-title">
            <img src={cotecmarLogo} alt="COTECMAR" className="sidebar-logo" />
            <span>Navegación</span>
          </div>
          <button 
            className="sidebar-close-btn" 
            onClick={() => setShowSidebar(false)} 
            title="Cerrar Menú"
          >
            <FaTimes />
          </button>
        </div>
        <nav className="sidebar-nav">
          <button 
            className="sidebar-item"
            onClick={() => {
              navigate("/admin");
              setShowSidebar(false);
            }}
          >
            <FaFolderOpen className="sidebar-icon" />
            <span>Mis Proyectos</span>
          </button>
          
          <button 
            className="sidebar-item active" 
            style={{ display: currentUser?.role === 'admin' ? 'flex' : 'none' }}
            onClick={() => setShowSidebar(false)}
          >
            <FaUsers className="sidebar-icon" />
            <span>Gestión de Usuarios</span>
          </button>
          
          <button 
            className="sidebar-item" 
            style={{ display: currentUser?.role === 'admin' ? 'flex' : 'none' }}
            onClick={() => {
              navigate("/admin/permissions");
              setShowSidebar(false);
            }}
          >
            <FaShieldAlt className="sidebar-icon" />
            <span>Gestión de Permisos</span>
          </button>
          
          <button 
            className="sidebar-item"
            onClick={() => {
              navigate("/gallery");
              setShowSidebar(false);
            }}
          >
            <FaImages className="sidebar-icon" />
            <span>Galería de Proyecto</span>
          </button>
        </nav>
      </div>

      <DynamicNavbar
        showBackButton={false}
        title="Gestión de Usuarios"
        subtitle="Crea cuentas, controla el acceso y define qué barcos puede ver cada usuario."
        leftActions={
          <button 
            className="hamburger-btn" 
            onClick={() => setShowSidebar(!showSidebar)}
            title="Abrir Menú"
            style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'transparent', border: 'none', color: 'inherit', fontSize: '20px', cursor: 'pointer', padding: '8px', marginRight: '8px' }}
          >
            <FaBars />
          </button>
        }
      >
        <div className="profile-container" style={{ position: 'relative', marginLeft: '8px' }}>
          <button className="profile-btn" onClick={() => setMenuOpen((v) => !v)}>
            <div className="avatar-wrapper">
              <FaUserCircle className="user-avatar-icon" />
            </div>
              <span className="avatar-username">{currentUser?.name || 'Perfil'}</span>
              <FaChevronDown style={{ fontSize: '12px', color: 'rgba(255,255,255,0.7)' }} />
            </button>
            {menuOpen && (
              <div className="profile-dropdown-menu" onMouseLeave={() => setMenuOpen(false)}>
                <div className="dropdown-user-info">
                  <p className="user-name">{currentUser?.name || 'Usuario'}</p>
                  <p className="user-role">{currentUser?.email || ''}</p>
                </div>
                <hr className="dropdown-divider" />
                <button className="dropdown-item" onClick={() => { setMenuOpen(false); navigate('/gallery'); }}>
                  <FaImages className="dropdown-icon" /> Galería de proyectos
                </button>
                <button className="dropdown-item" onClick={() => { setMenuOpen(false); setShowPasswordSettings(true); }}>
                  <FaKey className="dropdown-icon" /> Cambiar contraseña
                </button>
                <button className="dropdown-item" onClick={() => { setMenuOpen(false); setShowSceneCalibration(true); }}>
                  <FaMapMarkerAlt className="dropdown-icon" /> Calibrar orientación
                </button>
                <button className="dropdown-item" onClick={() => { setMenuOpen(false); onToggleDarkMode && onToggleDarkMode(); }}>
                  {darkMode ? <FaSun className="dropdown-icon" /> : <FaMoon className="dropdown-icon" />} {darkMode ? 'Activar modo claro' : 'Activar modo oscuro'}
                </button>
                <hr className="dropdown-divider" />
                <button className="dropdown-item logout" onClick={onLogout || (() => { authService.logout(); navigate('/login'); })}>
                  <FaSignOutAlt className="dropdown-icon" /> Cerrar sesión
                </button>
              </div>
            )}
          </div>
      </DynamicNavbar>

      <div className="user-management__content">
        <section className="user-management__form-panel">
          <div className="panel-title">
            <FaUserCog />
            <h2>{form.id ? "Editar usuario" : "Nuevo usuario"}</h2>
          </div>

          <form onSubmit={handleSubmit} className="user-form">
            <label>
              Nombre
              <input
                type="text"
                value={form.name}
                onChange={(e) => handleChange("name", e.target.value)}
                required
              />
            </label>

            <label>
              Correo
              <input
                type="email"
                value={form.email}
                onChange={(e) => handleChange("email", e.target.value)}
                required
              />
            </label>

            <label>
              Celular
              <input
                type="text"
                value={form.phone}
                onChange={(e) => handleChange("phone", e.target.value)}
                placeholder="3001234567"
              />
            </label>

            <label>
              {form.id ? "Nueva contraseña (opcional)" : "Contraseña"}
              <input
                type="password"
                value={form.password}
                onChange={(e) => handleChange("password", e.target.value)}
                required={!form.id}
              />
            </label>

            <label>
              Rol
              <select
                value={form.role}
                onChange={(e) => handleChange("role", e.target.value)}
              >
                <option value="user">Usuario</option>
                <option value="project_admin">Administrador de Proyectos</option>
                <option value="admin">Administrador Principal</option>
              </select>
            </label>

            <label className="checkbox-row">
              <input
                type="checkbox"
                checked={form.isActive}
                onChange={(e) => handleChange("isActive", e.target.checked)}
              />
              Cuenta activa
            </label>

            {message && <div className="feedback success">{message}</div>}
            {error && <div className="feedback error">{error}</div>}

            <div className="user-form__actions">
              <button type="submit" className="primary-btn" disabled={saving}>
                {form.id ? <FaSave /> : <FaPlus />}
                {saving ? "Guardando..." : form.id ? "Actualizar usuario" : "Crear usuario"}
              </button>
              {form.id && (
                <button type="button" className="secondary-btn" onClick={resetForm}>
                  Cancelar edición
                </button>
              )}
            </div>
          </form>
        </section>

        <section className="user-management__list-panel">
          <div className="panel-title">
            <FaUsers />
            <h2>Usuarios registrados</h2>
          </div>

          {loading ? (
            <div className="loading-state">Cargando usuarios...</div>
          ) : (
            <div className="users-list">
              {users.map((user) => (
                <article key={user.id} className="user-card">
                  <div className="user-card__head">
                    <div>
                      <h3>{user.name}</h3>
                      <p>
                        <FaEnvelope /> {user.email}
                      </p>
                      <p>
                        <FaPhone /> {user.phone || "Sin celular"}
                      </p>
                    </div>
                    <div className="user-badges">
                      <span className={`badge badge--${user.role}`}>
                        {user.role === "admin" || user.role === "project_admin" ? <FaUserShield /> : <FaUsers />}
                        {user.role === "admin" ? "Admin" : user.role === "project_admin" ? "Admin Proy." : "Usuario"}
                      </span>
                      <span className={`badge badge--${user.isActive ? "active" : "inactive"}`}>
                        {user.isActive ? "Activo" : "Inactivo"}
                      </span>
                    </div>
                  </div>

                  <div className="user-card__actions">
                    <button className="secondary-btn" onClick={() => startEdit(user)}>
                      Editar
                    </button>
                    <button className="danger-btn" onClick={() => handleDelete(user)}>
                      <FaTrash /> Eliminar
                    </button>
                  </div>
                </article>
              ))}

              {users.length === 0 && (
                <div className="empty-state">
                  Todavía no hay usuarios creados.
                </div>
              )}
            </div>
          )}
        </section>
      </div>

      <ConfirmModal
        isOpen={modal.isOpen}
        onClose={() => setModal((prev) => ({ ...prev, isOpen: false }))}
        onConfirm={modal.onConfirm}
        title={modal.title}
        message={modal.message}
        type="danger"
        confirmText="Eliminar"
      />
    </div>
  );
};

export default UserManagement;
